async () => {
  const rows = [];
  for (let p = 1; p <= 10; p++) {
    const html = await (await fetch('?page=' + p)).text();
    const doc = new DOMParser().parseFromString(html, 'text/html');
    doc.querySelectorAll('table tr').forEach(tr => {
      const c = [...tr.querySelectorAll('td')].map(td => td.textContent.trim());
      if (c.length) rows.push(c);
    });
  }
  const m = rows.filter(r => r[1] === 'Northwind' && r[3] === 'overdue');
  const odd = rows.filter(r => /northwind/i.test(r[1]) && r[1] !== 'Northwind' || /overdue/i.test(r[3]) && r[3] !== 'overdue');
  const cents = m.reduce((s, r) => s + Math.round(parseFloat(r[2].replace(/[$,]/g, '')) * 100), 0);
  const ids = rows.map(r=>r[0]);
  return { n: rows.length, uniq: new Set(ids).size, m, total: cents / 100, odd };
}
